-- Window functions, CTE chains, retention and cohort analytics
SELECT user_id, ts, row_number() OVER (PARTITION BY user_id ORDER BY ts) AS rn FROM web_events;
SELECT user_id, ts, lagInFrame(ts) OVER (PARTITION BY user_id ORDER BY ts ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS prev_ts FROM web_events;
SELECT user_id, ts, lag(ts, 1) OVER (PARTITION BY user_id ORDER BY ts) AS prev FROM web_events;
SELECT day, revenue, avg(revenue) OVER (ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS ma7 FROM daily_rev;
SELECT day, revenue, sum(revenue) OVER (ORDER BY day RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum FROM daily_rev;
SELECT user_id, amount, rank() OVER w AS r, dense_rank() OVER w AS dr FROM orders WINDOW w AS (PARTITION BY user_id ORDER BY amount DESC);
SELECT id, ntile(4) OVER (ORDER BY score) AS quartile, first_value(score) OVER (ORDER BY score) AS mn, last_value(score) OVER (ORDER BY score ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS mx FROM scores;
SELECT id, percent_rank() OVER (ORDER BY score), cume_dist() OVER (ORDER BY score) FROM scores;
WITH daily AS (SELECT toDate(ts) AS d, count() AS c FROM web_events GROUP BY d) SELECT d, c FROM daily ORDER BY d;
WITH 7 AS days SELECT count() FROM web_events WHERE ts >= now() - INTERVAL days DAY;
WITH (SELECT max(ts) FROM web_events) AS latest SELECT count() FROM web_events WHERE ts = latest;
WITH first_seen AS (SELECT user_id, min(toDate(ts)) AS cohort FROM web_events GROUP BY user_id), activity AS (SELECT DISTINCT user_id, toDate(ts) AS d FROM web_events) SELECT f.cohort, dateDiff('day', f.cohort, a.d) AS age, uniq(a.user_id) AS users FROM first_seen AS f INNER JOIN activity AS a ON a.user_id = f.user_id GROUP BY f.cohort, age ORDER BY f.cohort, age;
WITH a AS (SELECT 1 AS x), b AS (SELECT x + 1 AS y FROM a), c AS (SELECT y * 2 AS z FROM b), d AS (SELECT z + 10 AS w FROM c) SELECT * FROM d;
WITH RECURSIVE t AS (SELECT 1 AS n UNION ALL SELECT n + 1 FROM t WHERE n < 5) SELECT * FROM t;
SELECT retention(ts = today(), ts = today() - 1, ts = today() - 7) FROM web_events GROUP BY user_id;
SELECT sequenceMatch('(?1)(?2)')(ts, event = 'a', event = 'b') FROM web_events GROUP BY user_id;
SELECT user_id, sum(amount) OVER (PARTITION BY user_id ORDER BY ts) / sum(amount) OVER (PARTITION BY user_id) AS frac FROM orders;
SELECT * FROM (SELECT user_id, row_number() OVER (PARTITION BY user_id ORDER BY ts DESC) AS rn FROM web_events) WHERE rn = 1;
SELECT x FROM (SELECT * FROM (SELECT * FROM (SELECT number AS x FROM numbers(100)) WHERE x > 10) WHERE x < 90) WHERE x % 2 = 0;
SELECT a.x, b.y, c.z, d.w, e.v FROM a INNER JOIN b ON a.id = b.id LEFT JOIN c ON b.id = c.id LEFT JOIN d ON c.id = d.id ANY LEFT JOIN e ON d.id = e.id;
SELECT * FROM a ASOF JOIN b ON a.id = b.id AND a.ts >= b.ts;
SELECT * FROM a GLOBAL ANY LEFT JOIN b USING (id);
SELECT * FROM a INNER JOIN b USING (id, ts);
SELECT * FROM a CROSS JOIN b;
SELECT * FROM a FULL OUTER JOIN b ON a.id = b.id;
SELECT * FROM a LEFT SEMI JOIN b ON a.id = b.id;
SELECT * FROM a LEFT ANTI JOIN b ON a.id = b.id;
SELECT id FROM a UNION ALL SELECT id FROM b UNION ALL SELECT id FROM c;
SELECT id FROM a UNION DISTINCT SELECT id FROM b;
SELECT id FROM a INTERSECT SELECT id FROM b;
SELECT id FROM a EXCEPT SELECT id FROM b;
